const RFP_CSS=":root{--sp-ink:#24332f;--sp-muted:#687972;--sp-soft:#f7f8f4;--sp-border:#dce5de;--sp-paper:#fff;--sp-green:#146956;--sp-deep:#143b38;--sp-teal:#248e75;--sp-amber:#b77a27;--sp-sand:#e9e5d6;--sp-warn:#8d6223;--sp-danger:#a24c42;--sp-font:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif}
*{box-sizing:border-box}html,body{margin:0;max-width:100%;min-width:0;overflow-x:hidden}body{font-family:var(--sp-font);color:var(--sp-ink);font-size:13.0px;line-height:1.55;background:var(--sp-soft)}button,input,textarea,select{font:inherit;color:inherit}button{cursor:pointer}button:disabled{opacity:.48;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,[tabindex]:focus-visible{outline:3px solid #76cbbb;outline-offset:3px}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(26px,2.3vw,36px);letter-spacing:-1.2px;line-height:1.16;font-weight:750;margin:0 0 5px}h2{font-size:18.0px;line-height:1.32;font-weight:720;letter-spacing:-.35px;margin:0}h3{font-size:14.0px;font-weight:690;line-height:1.3;margin:0}p{line-height:1.55}svg{flex:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;clip:rect(0,0,0,0);white-space:nowrap;overflow:hidden;border:0}
.sp-shell{display:grid;grid-template-columns:225px minmax(0,1fr);min-height:100vh;max-width:100%}.sp-sidebar{position:sticky;top:0;height:100vh;display:flex;flex-direction:column;align-self:start;background:linear-gradient(180deg,#153f3d,#102e2b);padding:26px 12px 21px;color:#c9e0d6}.sp-app-name{margin:3px 8px 32px;min-height:54px;display:flex;align-items:center}.sp-app-name strong{display:block;color:#f8faf6;font-size:17.0px;line-height:1.25;font-weight:720;letter-spacing:-.2px;white-space:normal;overflow-wrap:anywhere}.sp-nav-category{font-size:12px;letter-spacing:.15em;color:#43594f;padding:0 12px 11px;font-weight:700}.sp-sidebar nav{display:flex;flex-direction:column;gap:5px}.sp-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid #d3dfd6;border-radius:8px;background:white;padding:9px 13px;min-height:37px;font-weight:650;white-space:normal;text-align:center;color:#345148;line-height:1.3}.sp-button:hover:not(:disabled){background:#eaf4ee;border-color:#a8c7b6}.sp-primary{background:#176f59;border-color:#176f59;color:#fff}.sp-primary:hover:not(:disabled){background:#0b5745;border-color:#0b5745}.sp-secondary{background:#f8faf6;color:#35695b}.sp-icon-only{width:38px;min-width:38px;height:38px;padding:6px;background:#fff;color:#33564c}.sp-text,.sp-ghost{border-color:transparent;background:transparent;color:#20715c;padding:5px 7px;font-weight:680;min-height:31px}.sp-text:hover:not(:disabled),.sp-ghost:hover:not(:disabled){background:#edf5ee;border-color:transparent}.sp-ghost{font-size:12px}.sp-danger{color:var(--sp-danger)}.sp-danger-button{background:#a65248;color:#fff;border-color:#a65248}.sp-mini{min-height:26px;width:28px;padding:3px;border-radius:7px;background:#edf5ec}.sp-nav-btn{background:transparent;border:1px solid transparent;color:#bcd6cb;justify-content:flex-start;text-align:left;width:100%;padding:12px 11px;font-size:13.0px;font-weight:560;border-radius:8px;min-height:45px;gap:12px}.sp-nav-btn:hover:not(:disabled){