chip.evaluating,.sp-chip.na{background:#e5ecff;color:#43594f}
.sp-desk-layout{display:grid;grid-template-columns:minmax(230px,.32fr) minmax(0,.68fr);gap:23px}.sp-desk-list{display:flex;flex-direction:column;gap:11px}.sp-side-section,.sp-section-title{display:flex;align-items:center;justify-content:space-between;gap:9px}.sp-side-section{margin:0 0 4px}.sp-rfp-tile{background:#fff;border:1px solid #dce6dc;border-radius:12px;padding:15px 16px 12px;box-shadow:0 2px 9px #243f3310}.sp-rfp-tile.active{border-color:#6ab09a;box-shadow:0 0 0 2px #e0f5e8 inset}.sp-rfp-tile>button{border:0;background:transparent;text-align:left;display:flex;flex-direction:column;gap:6px;padding:0;width:100%}.sp-rfp-tile>button:hover strong{color:#087858}.sp-rfp-tile small{font-size:12px;color:#43594f}.sp-rfp-tile strong{font-size:15.0px;line-height:1.3;color:#28443a}.sp-rfp-tile span{font-size:12px;color:#43594f}.sp-rfp-tile footer{padding-top:11px;margin-top:13px;border-top:1px solid #edf0e9;display:flex;align-items:center;justify-content:space-between;gap:8px}.sp-rfp-tile footer>span:last-child{font-size:12px;white-space:nowrap}.sp-command-card{border-radius:15px;background:#173d3b;color:white;padding:27px 29px 25px;position:relative;overflow:hidden;min-height:275px}.sp-command-card:before{content:'';position:absolute;right:-84px;top:-108px;width:310px;height:310px;border:1px solid #ffffff19;border-radius:50%;box-shadow:0 0 0 45px #ffffff06,0 0 0 96px #ffffff06;pointer-events:none}.sp-command-head{position:relative;display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.sp-command-head .sp-eyebrow{color:#43594f}.sp-command-head h2{font-size:24.0px;letter-spacing:-.75px;line-height:1.2;max-width:560px;margin:10px 0}.sp-command-head p{font-size:12px;color:#c7dad4;max-width:610px;margin:0}.sp-command-head .sp-chip{background:#ffffff20;color:#e7f2ee}.sp-cycle{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0;margin:27px 0 24px;position:relative}.sp-cycle-step{display:flex;align-items:center;flex-direction:column;gap:8px;position:relative;color:#43594f}.sp-cycle-step:after{content:'';position:absolute;top:14px;left:50%;width:100%;height:1px;background:#ffffff25;z-index:0}.sp-cycle-step:last-child:after{display:none}.sp-cycle-step span{position:relative;z-index:1;display:grid;place-items:center;background:#36534f;width:28px;height:28px;border-radius:50%;border:1px solid #78978c;color:#bdd2ca;font-size:12px;font-weight:700}.sp-cycle-step.complete span{background:#82d0ad;color:#163c34;border-color:#82d0ad}.sp-cycle-step.current span{box-shadow:0 0 0 5px #ffffff14}.sp-cycle-step b{font-size:12px;font-weight:580;white-space:nowrap}.sp-cycle-step.current b{color:#fff;font-weight:720}.sp-mini-stats{border-top:1px solid #ffffff2b;display:flex;padding-top:20px;gap:25px}.sp-mini-stats>div{display:flex;flex-direction:column;gap:3px;min-width:0}.sp-mini-stats b{font-size:27.0px;font-weight:710;letter-spacing:-.6px}.sp-mini-stats span{font-size:12px;color:#43594f}.sp-desk-bottom{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:19px;margin-top:20px}.sp-paper{background:white;border:1px solid #dde6dd;border-radius:13px;padding:22px;margin-bottom:20px;min-width:0;box-shadow:0 3px 13px #2642360c}.sp-section-title{margin-bottom:18px}.sp-section-title small{font-size:12px;color:#43594f}.sp-date-step{display:flex;align-items:center;gap:13px;border-top:1px solid #edf1ed;padding:14px 0}.sp-date-step>span{font-size:12px;color:#43594f}.sp-date-step>strong{font-size:12px;font-weight:650;flex:1}.sp-date-step>b{font-size:12px;white-space:nowrap}.sp-attention{display:flex;align-items:flex-start;gap:12px;padding:12px 0;border-top:1px solid #edf1ed}.sp-attention svg{color:#43594f;margin-top:3px}.sp-attention b{display:block;font-size:12px;line-height:1.35}.sp-attention small{display:block;color:#43594f;font-size:12px;margin-top:5px}.sp-empty-inline{font-size:12px;color:#43594f;padding:20px 0}.sp-empty{padding:28px 16px;text-align:center;background:#f7faf7;border:1px dashed #cddcd1;border-radius:10px;color:#43594f;font-size:12px}
.sp-planner{border-radius:13px;background:linear-gradient(135deg,#234f49,#38685f);padding:22px 24px;color:#f6fffa;margin-bottom:21px;overflow:hidden}.sp-schedule-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.sp-schedule-head .sp-eyebrow{color:#43594f}.sp-schedule-head strong{font-size:12px}.sp-schedule-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.sp-schedule-row>div{border:1px solid #ffffff2d;background:#ffffff12;border-radius:10px;padding:12px;display:flex;flex-wrap:wrap;align-items:center;gap:7px;font-size:12px}.sp-schedule-row b{width:100%;font-size:12px}.sp-schedule-row span{white-space:nowrap;color:#d7e6de}.sp-schedule-row em{height:1px;flex:1;min-width:4px;background:#a9d4ba}.sp-schedule-row small{display:block;width:100%;color:#b9dbc8}.sp-toolbar{display:flex;align-items:center;gap:9px;justify-content:space-between;margin-bottom:16px}.sp-toolbar label{display:flex;align-items:center;gap:8px;border:1px solid #d7e2d9;padding:0 10px;min-width:180px;flex:1;max-width:520px;background:#fff;border-radius:8px;height:39px}.sp-toolbar label svg{color:#43594f}.sp-toolbar input{border:0;outline:0;min-width:0;width:100%;font-size:12px}.sp-table-scroll{width:100%;max-width:100%;overflow-x:auto}.sp-table,.sp-matrix{border-collapse:collapse;width:100%;font-size:12px;text-align:left}.sp-table th{background:#f1f5ef;color:#43594f;font-size:12px;font-weight:760;padding:13px 12px;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}.sp-table td{padding:13px 12px;border-bottom:1px solid #edf1ed;color:#40574c;vertical-align:middle;max-width:310px;overflow-wrap:anywhere}.sp-table tr:last-child td{border:0}.sp-row-ops{min-width:150px}.sp-row-control{display:flex;align-items:center;gap:0}.sp-pager{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding-top:15px;color:#43594f;font-size:12px}.sp-pager>div{display:flex;gap:7px}
.sp-builder-top{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin-bottom:21px;border-radius:13px;padding:26px 31px;background:#edf4ea;border:1px solid #cbded1}.sp-builder-top h2{font-size:25.0px;margin:10px 0 8px;letter-spacing:-.65px}.sp-builder-top p{font-size:12px;color:#43594f;max-width:630px;margin:0}.sp-weight{display:flex;flex-direction:column;align-items:flex-end;gap:4px;min-width:140px;border-left:1px solid #c9dacc;padding-left:18px}.sp-weight strong{font-size:35.0px;letter-spacing:-1.1px}.sp-weight span{font-size:12px;color:#43594f;text-align:right}.sp-builder-layout{display:grid;grid-template-columns:222px minmax(0,1fr);gap:20px;align-items:start}.sp-section-index,.sp-vendor-index{border:1px solid var(--sp-border);border-radius:12px;background:#fff;padding:17px 10px;min-width:0}.sp-index-head{margin:2px 12px 17px}.sp-section-choice{width:100%;border:0;background:transparent;text-align:left;justify-content:space-between;font-size:12px;font-weight:600;padding:11px 12px;margin-bottom:3px;color:#43594f}.sp-section-choice.active{background:#e8f5e9;color:#0a6750}.sp-section-choice b{font-size:12px}.sp-help{font-size:12px;color:#43594f;border-top:1px solid #eff2eb;margin:13px 10px 0;padding-top:13px}.sp-requirement-list{padding:20px 26px}.sp-requirement{border-top:1px solid #e7eee6;padding:17px 0;display:flex;gap:14px;align-items:flex-start}.sp-req-num{font-size:12px;color:#43594f;min-width:23px;padding-top:3px}.sp-req-body{flex:1;min-width:0}.sp-req-body h3{font-size:14.0px;margin-bottom:7px}.sp-req-body p{font-size:12px;color:#43594f;margin:0 0 12px}.sp-req-meta{display:flex;align-items:center;flex-wrap:wrap;gap:7px}.sp-req-meta>span:not(.sp-chip){font-size:12px;color:#43594f;background:#f1f5f0;padding:4px 6px;border-radius:5px}.sp-req-right{min-width:70px;display:flex;flex-direction:column;align-items:flex-end;gap:3px}.sp-req-right strong{font-size:20.0px;letter-spacing:-.5px}
.sp-response-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px;align-items:start}.sp-vendor-index{padding:16px 8px}.sp-vendor-option{position:relative;display:flex;flex-direction:column;gap:5px;width:100%;text-align:left;border:1px solid transparent;border-radius:8px;padding:14px 12px 17px;background:transparent;overflow:hidden;margin-bottom:5px;color:#315249}.sp-vendor-option.active{border-color:#b6d8c1;background:#edf6ee}.sp-vendor-option span{font-size:13.0px;font-weight:730}.sp-vendor-option small{font-size:12px;color:#43594f}.sp-vendor-option i{display:block;height:3px;position:absolute;left:11px;bottom:7px;background:#48a77e;max-width:calc(100% - 22px);border-radius:8px}.sp-response-summary{border-radius:13px;background:#e8f0e9;padding:27px;display:flex;justify-content:space-between;gap:18px;align-items:center}.sp-response-summary h2{font-size:24.0px;margin:9px 0 4px}.sp-response-summary p{margin:0;font-size:12px;color:#43594f;max-width:580px}.sp-coverage-ring{width:98px;min-width:98px;height:98px;border:8px solid #a6d6b6;border-left-color:#cdded0;display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:50%;background:#fff}.sp-coverage-ring b{font-size:23.0px;line-height:1.2}.sp-coverage-ring span{font-size:12px;color:#43594f}.sp-response-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:15px 0}.sp-response-actions .sp-chip{margin-right:auto}.sp-response-sheet .sp-paper{padding:19px}
