function table(role,list){const cols=columns(role).filter(k=>visible(role+':'+k));const pageSize=Math.max(10,Math.min(50,Number(cfg.pageSize)||20)),key=role;let page=Math.max(0,st.pages[key]||0);const q=st.search.toLowerCase();const filtered=q?list.filter(r=>JSON.stringify(r.data).toLowerCase().includes(q)):list;const max=Math.max(0,Math.ceil(filtered.length/pageSize)-1);page=Math.min(page,max);st.pages[key]=page;const rows=filtered.slice(page*pageSize,(page+1)*pageSize);return '<div class="sp-table-scroll" role="region" aria-label="'+h(role)+' records" tabindex="0"><table class="sp-table"><thead><tr>'+cols.map(k=>'<th>'+h(colLabel(role,k))+'</th>').join('')+'<th>Actions</th></tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(k=>'<td data-label="'+h(colLabel(role,k))+'">'+readable(role,k,r)+'</td>').join('')+'<td class="sp-row-ops"><div class="sp-row-control">'+button('Edit','edit:'+role+':'+r.id,'sp-ghost',!enabled)+button('Duplicate','duplicate:'+role+':'+r.id,'sp-ghost',!enabled)+button('Archive','archive:'+role+':'+r.id,'sp-ghost sp-danger',!enabled)+'</div></td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="sp-empty">No matching records. '+(enabled?'Choose New to create the first record.':'')+'</div>':'')+'</div><div class="sp-pager"><span>'+(dataset[role].complete?'Authorized records':'Visible loaded rows')+' '+filtered.length+' · Page '+(page+1)+' of '+(max+1)+'</span><div>'+button('Previous','page:'+key+':prev','sp-secondary',page===0)+button('Next','page:'+key+':next','sp-secondary',page===max)+'</div></div>';
}
