function projects(){return pageHead('RFP projects','Sourcing mandates, dates and versioned work scopes.',button(ico('plus')+' Create RFP','new:projects','sp-primary',!enabled))+warn(['projects'])+'<div class="sp-planner"><div class="sp-schedule-head"><span class="sp-eyebrow">SOURCING CALENDAR</span><strong>'+h(allProjects.length)+' managed RF'+(allProjects.length===1?'P':'Ps')+'</strong></div><div class="sp-schedule-row">'+allProjects.slice(0,6).map(r=>'<div><b>'+h(short(r.data.name,38))+'</b><span>'+dFmt(r.data.issuedAt)+'</span><em></em><span>'+dFmt(r.data.responseDue)+'</span><small>'+h(r.data.status||'Draft')+'</small></div>').join('')+'</div></div><section class="sp-paper">'+toolbar('projects')+table('projects',allProjects)+'</section>';
