const SECTIONS=['Clinical delivery','Quality','Geography','Timeline','Commercial'];
function builder(){const items=reqs(),groups=SECTIONS.map(z=>({name:z,rows:items.filter(r=>r.data.section===z)})),sum=items.reduce((a,r)=>a+(Number(r.data.weight)||0),0);const arr=st.section==='All'?items:items.filter(r=>r.data.section===st.section);st.reqPage=Math.min(st.reqPage||0,Math.max(0,Math.ceil(arr.length/12)-1));const shown=arr.slice(st.reqPage*12,st.reqPage*12+12);return pageHead('Scope & criteria','Compose a consistent, auditable request before comparing CRO proposals.',button(ico('plus')+' Add requirement','new:requirements','sp-primary',!enabled))+warn(['projects','requirements'])+'<div class="sp-builder-top"><div><span class="sp-eyebrow">RFP DOCUMENT · '+projectLabel()+'</span><h2>What should every CRO answer?</h2><p>Define mandatory evidence, scoring weights and the requested answer type. Issued requirements retain their original revisions.</p></div><div class="sp-weight"><strong>'+h(items.length?sum.toFixed(0)+'%':'—')+'</strong><span>Current weights · '+(items.length&&sum===100?'Balanced': 'Review before scoring')+'</span></div></div><div class="sp-builder-layout"><aside class="sp-section-index"><div class="sp-index-head">RFP SECTIONS</div>'+button('All requirements <b>'+items.length+'</b>','section:All','sp-section-choice '+(st.section==='All'?'active':''))+groups.map(g=>button(h(g.name)+' <b>'+g.rows.length+'</b>','section:'+g.name,'sp-section-choice '+(st.section===g.name?'active':''))).join('')+'<div class="sp-help">Requirement versions and source responses are separate records. Changing published questions requires an explicit new revision.</div></aside><section class="sp-paper sp-requirement-list"><div class="sp-section-title"><h2>'+h(st.section==='All'?'All criteria':st.section)+'</h2>'+button('New requirement '+ico('plus'),'new:requirements','sp-secondary',!enabled)+'</div>'+(arr.length?shown.map((r,i)=>'<article class="sp-requirement"><span class="sp-req-num">'+String(i+1).padStart(2,'0')+'</span><div class="sp-req-body"><h3>'+h(short(r.data.name,135))+'</h3><p>'+h(short(r.data.evidence||'Supporting evidence not specified',180))+'</p><div class="sp-req-meta"><span>'+h(r.data.section)+'</span><span>'+h(r.data.answerType)+'</span>'+badge(r.data.mandatory===true?'Mandatory':'Optional')+'<span>v'+h(r.data.version||'1')+'</span></div></div><div class="sp-req-right"><strong>'+h(r.data.weight)+'%</strong>'+button('Edit','edit:requirements:'+r.id,'sp-text',!enabled)+button('Duplicate','duplicate:requirements:'+r.id,'sp-text',!enabled)+button('Archive','archive:requirements:'+r.id,'sp-text sp-danger',!enabled)+'</div></article>').join(''):'<div class="sp-empty">No requirements in this section. Use New requirement to add a criterion.</div>')+'<div class="sp-pager"><span>Requirements '+(st.reqPage*12+1)+'–'+Math.min((st.reqPage+1)*12,arr.length)+' of '+arr.length+'</span><div>'+button('Previous','req-prev','sp-secondary',st.reqPage===0)+button('Next','req-next','sp-secondary',(st.reqPage+1)*12>=arr.length)+'</div></div></section></div>';
}
function responses(){const invited=invites();if(!st.provider||!invited.some(x=>x.id===st.provider))st.provider=invited[0]?.id||'';const inv=activeInv(),cov=inv?vendorCoverage(inv):null;const associated=inv?records('responses').filter(x=>x.data.invitationId===inv.id):[];const clar=inv?records('clarifications').filter(x=>x.data.invitationId===inv.id):[];return pageHead('CRO responses','Record external bids and clarifications, without sending messages to suppliers.',button(ico('plus')+' Invite CRO','new:invitations','sp-primary',!enabled)+button('New provider','new:providers','sp-secondary',!enabled))+warn(['projects','providers','invitations','requirements','responses','clarifications'])+'<div class="sp-response-layout"><aside class="sp-vendor-index"><div class="sp-index-head">BID PARTICIPANTS</div>'+ (invited.length?invited.map(v=>{const c=vendorCoverage(v);return '<button type="button" data-action="choose-provider:'+h(v.id)+'" class="sp-vendor-option '+(v.id===st.provider?'active':'')+'"><span>'+h(short(lookup('providers',v.data.providerId),48))+'</span><small>'+h(v.data.status)+' · '+(c.pct===null?'Coverage unknown':c.pct+'% provided')+'</small><i style="width:'+(c.pct||0)+'%"></i></button>';}).join(''):'<div class="sp-empty">No providers invited to this RFP.</div>')+'</aside><section class="sp-response-sheet"><div class="sp-response-summary"><div><span class="sp-eyebrow">RECEIVED BID WORKSHEET</span><h2>'+h(inv?lookup('providers',inv.data.providerId):'Choose a CRO')+'</h2><p>'+h(inv?.data.notes||'Manually log the vendor’s documented responses and internal clarification trail.')+'</p></div><div class="sp-coverage-ring"><b>'+(cov?.pct==null?'—':cov.pct+'%')+'</b><span>provided</span></div></div><div class="sp-response-actions">'+badge(inv?.data.status||'Not invited')+button('Add answer','new:responses','sp-secondary',!inv||!enabled)+button('New clarification','new:clarifications','sp-secondary',!inv||!enabled)+'</div><section class="sp-paper"><div class="sp-section-title"><h2>Answer register</h2><small>One response per criterion and CRO</small></div>'+table('responses',associated)+'</section><section class="sp-paper"><div class="sp-section-title"><h2>Clarification log</h2><small>Replies must have recorded sources</small></div>'+table('clarifications',clar)+'</section><section class="sp-paper"><div class="sp-section-title"><h2>Invitation history</h2></div>'+table('invitations',invited)+'</section><section class="sp-paper"><div class="sp-section-title"><h2>Provider directory</h2>'+button('Add provider','new:providers','sp-secondary',!enabled)+'</div>'+table('providers',records('providers'))+'</section></section></div>';
}
function evaluation(){const inv=invites(),rqs=reqs();st.comparePage=Math.min(st.comparePage||0,Math.max(0,Math.ceil(inv.length/3)-1));st.reqPage=Math.min(st.reqPage||0,Math.max(0,Math.ceil(rqs.length/7)-1));const group=inv.slice(st.comparePage*3,st.comparePage*3+3),qq=rqs.slice(st.reqPage*7,st.reqPage*7+7);const roles=['projects','requirements','invitations','responses','reviews'];let weights=rqs.reduce((t,r)=>t+Number(r.data.weight||0),0);return pageHead('Evaluation room','Compare CRO evidence against identical weighted criteria.',button(ico('plus')+' Add reviewer score','new:reviews','sp-primary',!enabled))+warn(roles)+'<div class="sp-eval-summary"><div><span class="sp-eyebrow">REVIEW CONDITIONS</span><strong>'+h(weights)+'% <small>of 100% criterion weights</small></strong><p>Missing mandatory answers, unresolved reviews or duplicate evidence withhold the comparative score.</p></div><div class="sp-eval-count"><b>'+inv.length+'</b><span>Bid participants</span></div><div class="sp-eval-count"><b>'+rqs.length+'</b><span>Criteria</span></div></div><section class="sp-paper"><div class="sp-section-title"><h2>Side-by-side comparison</h2><div class="sp-pagination-top">'+button('Previous CROs','compare-prev','sp-secondary',st.comparePage===0)+button('Next CROs','compare-next','sp-secondary',(st.comparePage+1)*3>=inv.length)+'</div></div><p class="sp-matrix-help">Scroll this comparison region horizontally on narrow screens. Vendors '+(st.comparePage*3+1)+'–'+Math.min((st.comparePage+1)*3,inv.length)+' of '+inv.length+'.</p><div class="sp-matrix-scroll" role="region" aria-label="Supplier evaluation comparison" tabindex="0"><table class="sp-matrix"><thead><tr><th>Scoring criterion</th>'+group.map(v=>'<th><strong>'+h(short(lookup('providers',v.data.providerId),60))+'</strong><small>'+h(v.data.status)+'</small></th>').join('')+'</tr></thead><tbody>'+qq.map(q=>'<tr><th>'+h(short(q.data.name,94))+'<span>'+h(q.data.weight)+'% · '+(q.data.mandatory===true?'Mandatory':'Optional')+'</span></th>'+group.map(v=>{const ans=responseFor(v.id,q.id),rev=reviewsFor(v.id,q.id);const good=ans.length===1&&ans[0].data.status==='Provided'&&s(ans[0].data.answer);return '<td>'+badge(ans.length!==1?'Unverified':ans[0].data.status)+'<strong>'+(rev.length&&rev.every(x=>x.data.status==='Reviewed')?h(rev.map(x=>x.data.score).join(' / '))+'/5':'Not scored')+'</strong><small>'+h(good?'Response on file':'Answer missing or incomplete')+'</small></td>';}).join('')+'</tr>').join('')+'<tr class="sp-total"><th>Weighted comparison <span>Only complete, approved evidence</span></th>'+group.map(v=>{const x=scoreFor(v);return '<td><strong>'+(x.score===null?'—':x.score.toFixed(1)+'%')+'</strong><small>'+h(x.reason||'Comparable; not an award decision')+'</small></td>';}).join('')+'</tr></tbody></table></div><div class="sp-pager"><span>Criteria page '+(st.reqPage+1)+' of '+Math.max(1,Math.ceil(rqs.length/7))+'</span><div>'+button('Previous criteria','req-prev','sp-secondary',st.reqPage===0)+button('Next criteria','req-next','sp-secondary',(st.reqPage+1)*7>=rqs.length)+'</div></div></section><section class="sp-paper"><div class="sp-section-title"><h2>Reviewer evidence</h2>'+button('Add score '+ico('plus'),'new:reviews','sp-text',!enabled)+'</div>'+table('reviews',records('reviews').filter(r=>group.some(v=>v.id===r.data.invitationId)))+'</section>';
}
function award(){const decisions=records('awards').filter(own),candidates=decisions.filter(x=>x.data.status==='Approved');let approved=ready(allRoles)&&candidates.length===1?candidates[0]:null;let inv=approved?byId('invitations',approved.data.invitationId):null;if(approved&&(!inv||inv.data.status!=='Received'||!okDate(inv.data.receivedAt)||!s(approved.data.author)||!s(approved.data.rationale)||!okDate(approved.data.approvedAt)||scoreFor(inv).score===null||records('clarifications').some(x=>x.data.invitationId===inv.id&&x.data.status==='Open')))approved=null;const source=['projects','invitations','requirements','responses','reviews','awards','clarifications'];return pageHead('Award memo','Document a defensible selection and a controlled handoff.',button(ico('plus')+' New decision','new:awards','sp-primary',!enabled))+warn(source)+'<div class="sp-award-layout"><section class="sp-award-main"><div class="sp-award-document"><div class="sp-doc-header"><span>PROCUREMENT DECISION RECORD</span><b>RFP · '+h(short(project()?.data.study||'Study not set',35))+'</b></div><h2>'+h(project()?.data.name||'Select an RFP')+'</h2><p class="sp-doc-intro">An approved award requires a sponsor approver, decision rationale, complete mandatory responses and a reviewed scoring basis. It does not send vendor communications or sign a contract.</p><div class="sp-award-state"><span>Current verified award</span><strong>'+h(approved?lookup('providers',inv?.data.providerId):(candidates.length?'Historical approval needs reconciliation':'No approved selection'))+'</strong>'+badge(approved?'Approved':'Draft or pending')+'</div><dl class="sp-decision-fields"><div><dt>Accountable approver</dt><dd>'+h(approved?.data.author||'Not approved')+'</dd></div><div><dt>Decision date</dt><dd>'+dFmt(approved?.data.approvedAt)+'</dd></div><div><dt>Conditions / caveats</dt><dd>'+h(short(approved?.data.caveats||'Not recorded',350))+'</dd></div><div><dt>Oversight handoff</dt><dd>'+h(short(approved?.data.handoffRef||'Not linked',150))+'</dd></div></dl><div class="sp-award-note"><b>Decision rationale</b><p>'+h(approved?.data.rationale||'Record a rationale and submit the proposed decision through TrialAgents review.')+'</p></div></div></section><aside class="sp-award-side"><section class="sp-paper"><div class="sp-section-title"><h2>Decision checklist</h2></div>'+[['Complete requirements',ready(['projects','requirements'])&&reqs().length>0],['All source reads verified',ready(source)],['Award basis reviewed',!!approved],['Decision date recorded',!!approved&&okDate(approved.data.approvedAt)]].map(([label,yes])=>'<div class="sp-checkline">'+badge(yes?'Verified':'Pending')+'<span>'+label+'</span></div>').join('')+'</section><section class="sp-paper"><div class="sp-section-title"><h2>ChatGPT summary</h2></div><p class="sp-note">Generate a draft using only authorized CRO bids, criteria, reviews and decision evidence. ChatGPT cannot select the CRO or send an award notice.</p>'+button('Prepare drafting request','prompt','sp-secondary')+(st.prompt?'<div class="sp-prompt"><b>Copy this request into ChatGPT</b><p>'+h('Read current authorized Sponsor RFP Management records for project '+(project()?.data.name||'[select project]')+'. Include the exact evidence IDs, requirements, reviewer disagreement, missing responses and decision conditions. Draft an internal award memo with citations to saved records. Do not infer a winner, disclose restricted proposals, write a new approval, email a CRO or claim contract signature. Propose edits for human review only.')+'</p></div>':'')+'</section></aside></div><section class="sp-paper"><div class="sp-section-title"><h2>Decision history</h2>'+button('New decision '+ico('plus'),'new:awards','sp-text',!enabled)+'</div>'+table('awards',decisions)+'</section>';
}
const formField=(role,f,d)=>{let value=d[f.k];if(value===undefined||value===null)value='';const n=' name="'+h(f.k)+'" data-action="field:'+h(f.k)+'" data-ui-state="true" ';let control='';if(f.type==='long')control='<textarea'+n+' rows="3">'+h(value)+'</textarea>';else if(f.type==='select')control='<select'+n+'><option value="">Select</option>'+f.arg.map(x=>'<option value="'+h(x)+'" '+(x===value?'selected':'')+'>'+h(x)+'</option>').join('')+'</select>';else if(f.type==='boolean')control='<select'+n+'><option value="true" '+([true,'true'].includes(value)?'selected':'')+'>Yes</option><option value="false" '+([false,'false'].includes(value)?'selected':'')+'>No</option></select>';else if(f.type==='ref'){const items=records(f.arg);control='<select'+n+'><option value="">Choose '+h(f.label)+'</option>'+items.map(x=>'<option value="'+h(x.id)+'" '+(x.id===value?'selected':'')+'>'+h(short(x.data.name,80))+'</option>').join('')+'</select>';}else control='<input'+n+' type="'+(f.type==='number'?'number':f.type==='date'?'date':'text')+'" '+(f.type==='number'?'step="1"':'')+' value="'+h(value)+'">';return '<label class="sp-field"><span>'+h(f.label)+(f.required?' <b>*</b>':'')+'</span>'+control+'</label>';};
const editor=()=>{if(!st.editor)return '';const ed=st.editor;return '<div class="sp-overlay"><aside class="sp-drawer" role="dialog" aria-modal="true" aria-label="Edit '+h(ed.role)+'"><header><div><span class="sp-eyebrow">TRIALAGENTS REVIEWED CHANGE</span><h2>'+h((ed.mode==='edit'?'Edit ':ed.mode==='duplicate'?'Duplicate ':'New ')+ed.role.slice(0,-1))+'</h2><p>Proposal only. Saving requires separate host confirmation.</p></div>'+button(ico('close'),'close-editor','sp-icon-only')+'</header>'+(ed.error?'<div class="sp-form-error" role="alert">'+h(ed.error)+'</div>':'')+'<form data-action="save" class="sp-drawer-form">'+[...columns(ed.role).filter(k=>visible(ed.role+':'+k)),...F[ed.role].map(f=>f.k).filter(k=>!columns(ed.role).filter(k=>visible(ed.role+':'+k)).includes(k))].map(k=>F[ed.role].find(f=>f.k===k)).filter(f=>f&&f.k!=='archived'&&bindings[ed.role].writable.has(f.k)&&(st.extraFields||columns(ed.role).includes(f.k)&&visible(ed.role+':'+f.k))).map(f=>formField(ed.role,f,ed.draft)).join('')+button(st.extraFields?'Hide additional fields':'Show additional fields','extra-fields','sp-secondary')+'<div class="sp-form-buttons"><button type="submit" class="sp-button sp-primary">Propose for review</button>'+button('Cancel','close-editor','sp-secondary')+'</div></form></aside></div>';};
const confirm=()=>st.confirm?'<div class="sp-overlay"><div class="sp-dialog" role="alertdialog" aria-modal="true"><span class="sp-eyebrow">REVIEW REQUIRED</span><h2>Archive this record?</h2><p>This proposes an archived flag, not permanent deletion. Linked evidence may prevent archival. The original version will be checked.</p>'+(st.notice?'<div role="alert" class="sp-form-error">'+h(st.notice)+'</div>':'')+'<div>'+button('Cancel','cancel-archive','sp-secondary')+button('Propose archive','confirm-archive','sp-danger-button')+'</div></div></div>':'';
const nav=order.filter(visible).map(name=>button(ico(name)+'<span>'+h(navLabels[name])+'</span>','nav:'+name,'sp-nav-btn '+(st.tab===name?'active':''))).join('');
