const html=shell+(st.notice&&!st.editor&&!st.confirm?'<div class="sp-notice" role="status">'+h(st.notice)+button(ico('close'),'dismiss-notice','sp-icon-only')+'</div>':'')+screen+'</main></div>'+editor()+confirm();
